```python
"""Certificate-only scalar transfer verifier; does not import the producer.

Rebuilds all cuts by unordered pairs and +/-eta. Verifies safety by closure,
not graph search, and checks path witnesses at ONE common parameter. The parser,
model premises, theorem and operator are shared; this is not external review.
"""
from fractions import Fraction as Q
from itertools import combinations
from graph_model import parse, rat


def require(ok, why):
    if not ok:
        raise ValueError(why)


def required_cuts(s, t, limit):
    lower, upper = s.box[0]
    cuts = {lower,upper}
    for m in (s,t):
        for n in m.nodes:
            for a,b in combinations(n.actions,2):
                slope = a.v[0]-b.v[0]
                if slope:
                    for sign in (-1,1):
                        root = (sign*m.eta-a.c+b.c)/slope
                        if lower <= root <= upper:
                            cuts.add(root)
                            require(2*len(cuts)-1 <= limit, 'Cell resource limit')
    require(2*len(cuts)-1 <= limit, 'Cell resource limit')
    return sorted(cuts)


def permitted(m, node, a, x):
    return all(b.c-a.c+(b.v[0]-a.v[0])*x <= m.eta
               for b in node.actions)


def forbidden(m, a):
    return ((m.target in ('A','AB') and a.bit==0) or
            (m.target in ('B','AB') and not a.keep))


def check_safe(m, x, proof):
    require(set(proof)=={'type','nodes'} and proof['type']=='safe_set', 'Safe-set shape')
    require(isinstance(proof['nodes'],list) and all(type(v) is str for v in proof['nodes']),
            'Safe-set nodes must be identifiers')
    r = set(proof['nodes'])
    by = {n.name:n for n in m.nodes}
    require(len(r)==len(proof['nodes']) and r <= set(by) and m.root in r,
            'Safe set must contain root and only distinct original nodes')
    for h in r:
        for a in by[h].actions:
            if permitted(m,by[h],a,x):
                require(not forbidden(m,a), 'Reachable bad action in claimed safe set')
                require(set(a.next) <= r, 'Missing admissible positive-support successor')


def check_bad(m, x, proof):
    require(set(proof)=={'type','path'} and proof['type']=='bad_path', 'Bad-path shape')
    path = proof['path']
    require(isinstance(path,list) and 0 < len(path) <= len(m.nodes), 'Empty/too long bad path')
    by = {n.name:n for n in m.nodes}
    next_nodes = {m.root}
    for i, step in enumerate(path):
        require(isinstance(step,list) and len(step)==2 and all(type(z) is str for z in step),
                'Bad-path step shape')
        h,name = step
        require(h in next_nodes and h in by, 'Path root or successor mismatch')
        acts = {a.name:a for a in by[h].actions}
        require(name in acts, 'Unknown path action')
        a = acts[name]
        require(permitted(m,by[h],a,x), 'Action not admissible at the common theta')
        require(forbidden(m,a)==(i==len(path)-1), 'Path must stop at its first violation')
        next_nodes = set(a.next)


def verify(source, abstract, cert, max_cells=10000):
    """Validate continuous coverage OR a point counterexample, fail closed."""
    try:
        require(type(max_cells) is int and max_cells>=1, 'Positive cell limit required')
        s,t = parse(source),parse(abstract)
        require(len(s.box)==len(t.box)==1 and s.target==t.target, 'Scalar property mismatch')
        lower,upper = s.box[0]
        require(t.box[0][0] <= lower <= upper <= t.box[0][1], 'Domain inclusion failed')
        common = {'schema','source_hash','abstract_hash','target','domain','kind'}
        require(cert['schema']=='AH004-CELL-COVER-v1', 'Schema mismatch')
        require(cert['source_hash']==s.hash and cert['abstract_hash']==t.hash,
                'Original graph binding mismatch')
        require(cert['target']==s.target and cert['domain']==[str(lower),str(upper)],
                'Property/domain binding mismatch')
        if cert['kind']=='COUNTEREXAMPLE':
            require(set(cert)==common|{'theta','source_bad','abstract_safe'}, 'Counterexample fields')
            x = rat(cert['theta'])
            require(lower <= x <= upper, 'Witness outside source domain')
            check_bad(s,x,cert['source_bad']); check_safe(t,x,cert['abstract_safe'])
            return {'status':'COUNTEREXAMPLE_VALID','theta':str(x),
                    'scope':'Source bad and abstract safe at this allowed theta only.'}
        require(cert['kind']=='COVER' and set(cert)==common|{'cuts','cells'}, 'Cover fields')
        cuts = required_cuts(s,t,max_cells)
        require(isinstance(cert['cuts'],list), 'Cut list required')
        supplied = [rat(v) for v in cert['cuts']]
        require(lower in supplied, 'LOWER_ENDPOINT_OMITTED')
        require(upper in supplied, 'UPPER_ENDPOINT_OMITTED')
        missing = sorted(set(cuts)-set(supplied))
        require(not missing, 'COMPARISON_ROOT_OMITTED: '+','.join(map(str,missing)))
        require(supplied==cuts, 'Duplicate, unordered or noncanonical cuts')
        rows = cert['cells']
        require(isinstance(rows,list) and len(rows)==2*len(cuts)-1, 'Missing/extra point or open cell')
        safe_count = bad_count = 0
        for index,row in enumerate(rows):
            require(set(row)=={'kind','lo','hi','representative','side','proof'}, 'Cell fields')
            i = index//2
            point = index%2==0
            l,u = cuts[i],cuts[i] if point else cuts[i+1]
            x = l if point else (l+u)/2
            require((row['kind'],rat(row['lo']),rat(row['hi']),rat(row['representative'])) ==
                    ('point' if point else 'open',l,u,x), 'Wrong cell boundary/type/representative')
            if row['side']=='source_safe':
                check_safe(s,x,row['proof']); safe_count += 1
            elif row['side']=='abstract_bad':
                check_bad(t,x,row['proof']); bad_count += 1
            else:
                raise ValueError('Unknown cell implication proof')
        return {'status':'TRANSFER_VALID','domain':[str(lower),str(upper)],
                'points':len(cuts),'open_cells':len(cuts)-1,
                'source_safe_cells':safe_count,'abstract_bad_cells':bad_count,
                'scope':'Bad-parameter-set inclusion for one property, NOT path simulation or actual SAFE.'}
    except (ValueError,TypeError,KeyError,AttributeError,ZeroDivisionError,IndexError) as exc:
        return {'status':'UNKNOWN','reason':str(exc)}
