"""JSON CLI. Exit 0 means a completed calculation, not a safety verdict."""
import argparse
import json
from pathlib import Path
from cell_cover import build
from verify_cover import verify


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('mode',choices=('build','verify'))
    p.add_argument('source')
    p.add_argument('abstract')
    p.add_argument('certificate',nargs='?')
    p.add_argument('--max-cells',type=int,default=10000)
    a=p.parse_args()
    try:
        source=json.loads(Path(a.source).read_text(encoding='utf-8'))
        abstract=json.loads(Path(a.abstract).read_text(encoding='utf-8'))
        if a.mode=='build':
            if a.certificate is not None:p.error('build has no certificate input')
            result=build(source,abstract,a.max_cells)
        else:
            if a.certificate is None:p.error('verify needs a certificate JSON file')
            cert=json.loads(Path(a.certificate).read_text(encoding='utf-8'))
            result=verify(source,abstract,cert,a.max_cells)
    except (OSError,ValueError) as exc:
        result={'status':'UNKNOWN','reason':str(exc)}
    print(json.dumps(result,indent=2,sort_keys=True))


if __name__=='__main__':
    main()
