```python
"""Exact ONE-parameter predicate-transfer certificate producer.

Proves source-bad(theta) => abstract-bad(theta), not path simulation, physical
semantics, or an empirical safety claim. The checker is in verify_cover.py.
Both use the credited upstream schema/parser, but no shared cell/oracle code.
"""
from collections import deque
from fractions import Fraction as Q
from graph_model import parse

SCHEMA = 'AH004-CELL-COVER-v1'


def partition(s, t, max_cells):
    if len(s.box) != 1 or len(t.box) != 1 or s.target != t.target:
        raise ValueError('Same property and exactly one parameter required')
    lo, hi = s.box[0]
    if not t.box[0][0] <= lo <= hi <= t.box[0][1]:
        raise ValueError('Abstract domain must include the entire source domain')
    cuts = {lo, hi}
    for m in (s, t):
        for node in m.nodes:
            for a in node.actions:
                for b in node.actions:
                    slope = b.v[0] - a.v[0]
                    if slope:
                        x = (m.eta - b.c + a.c) / slope
                        if lo <= x <= hi:
                            cuts.add(x)
                            if 2*len(cuts)-1 > max_cells:
                                raise ValueError('Cell resource limit')
    cuts = sorted(cuts)
    cells = []
    for i, x in enumerate(cuts):
        if i:
            left = cuts[i-1]
            cells.append({'kind':'open', 'lo':str(left), 'hi':str(x),
                          'representative':str((left+x)/2)})
        cells.append({'kind':'point', 'lo':str(x), 'hi':str(x),
                      'representative':str(x)})
    if len(cells) > max_cells:
        raise ValueError('Cell resource limit')
    return cuts, cells


def inspect(m, x):
    """One-theta BFS, returning a closed safe set or a first-bad path."""
    by = {n.name:n for n in m.nodes}
    todo = deque([m.root])
    parents = {m.root:None}
    while todo:
        h = todo.popleft()
        node = by[h]
        scores = {a.name:a.c+a.v[0]*x for a in node.actions}
        top = max(scores.values(), default=Q(0))
        for a in node.actions:
            if top-scores[a.name] > m.eta:
                continue
            good = ((m.target=='B' or a.bit==1) and
                    (m.target=='A' or a.keep))
            if not good:
                path = [[h,a.name]]
                while parents[h] is not None:
                    h,name = parents[h]
                    path.append([h,name])
                return {'type':'bad_path', 'path':list(reversed(path))}
            for successor in a.next:
                if successor not in parents:
                    parents[successor] = (h,a.name)
                    todo.append(successor)
    return {'type':'safe_set', 'nodes':list(parents)}


def build(source, abstract, max_cells=10000):
    """UNKNOWN on unsupported/empty input or limits; no silent partial PASS."""
    try:
        if type(max_cells) is not int or max_cells < 1:
            raise ValueError('Positive cell limit required')
        s, t = parse(source), parse(abstract)
        cuts, cells = partition(s,t,max_cells)
        binding = {'schema':SCHEMA, 'source_hash':s.hash, 'abstract_hash':t.hash,
                   'target':s.target, 'domain':list(map(str,s.box[0]))}
        for cell in cells:
            x = Q(cell['representative'])
            src = inspect(s,x)
            if src['type']=='safe_set':
                cell['side'],cell['proof'] = 'source_safe',src
            else:
                dst = inspect(t,x)
                if dst['type']=='safe_set':
                    cert = dict(binding,kind='COUNTEREXAMPLE',theta=str(x),
                                source_bad=src,abstract_safe=dst)
                    return {'status':'COUNTEREXAMPLE','certificate':cert}
                cell['side'],cell['proof'] = 'abstract_bad',dst
        cert = dict(binding,kind='COVER',cuts=list(map(str,cuts)),cells=cells)
        return {'status':'TRANSFER_VALID','certificate':cert}
    except (ValueError,TypeError,KeyError,AttributeError,ZeroDivisionError) as exc:
        return {'status':'UNKNOWN','reason':str(exc)}
