"""Synthetic score/transition fixtures for scalar coverage, not real agents.

K actions leave the designated correction channel intact. O closes it before
request delivery; bit 1 permits a delivered update. Paired scores are explicit.
No counterfactual reward fidelity, welfare or measurement instrument is inferred.
"""
from copy import deepcopy
from fractions import Fraction as Q
from random import Random
from reduction_fixtures import graph, pair, leaf, fork


def scalar(raw, domain=(0,1)):
    out = deepcopy(raw)
    if not out['box']:
        out['box'] = [list(map(str,domain))]
        for n in out['nodes']:
            for a in n['actions']: a['v'] = ['0']
    return out


def safe_graph(domain=(0,1), target='B'):
    return graph([leaf('root',dim=1)], [domain], target=target)


def interior_tie(t=Q(1,3)):
    acts = pair('PLUS',True,-t,[1])+pair('MINUS',True,t,[-1])+pair('O',False,0,[0])
    source = graph([{'name':'root','actions':acts}], [(0,1)])
    abstract = deepcopy(source)
    for a in abstract['nodes'][0]['actions']:
        if a['base']=='O': a['c'] = str(Q(a['c'])-2)
    return source, abstract


def interval_bad(left=Q(1,3), right=Q(2,3)):
    root = {'name':'root','actions':pair('EXIT',True,0,[0])+
            pair('ENTER',True,-left,[1],('child',))+pair('O',False,-5,[0])}
    child = {'name':'child','actions':pair('KEEP',True,0,[1])+pair('O',False,right,[0])}
    return graph([root,child],[(0,1)]),safe_graph()


def contradictory_prefix():
    # ENTER requires theta>=3/4; child O requires theta<=1/4. No common theta.
    return interval_bad(Q(3,4),Q(1,4))


def dominated_extra():
    source = safe_graph()
    abstract = deepcopy(source)
    abstract['nodes'][0]['actions'] += pair('EXTRA',True,-10,[0])
    return source,abstract


def random_pair(seed):
    rng = Random(seed)
    count = 1+seed%4
    names = ['root']+['n'+str(i) for i in range(1,count)]
    nodes = []
    for i,name in enumerate(names):
        actions = []
        for b in range(2+seed%2):
            base = 'b'+str(b)
            keep = b!=1
            for bit in (0,1):
                # Deliberately asymmetric scores and successors; full pairing retained.
                nxt = [h for h in names[i+1:] if rng.randrange(3)==0]
                actions.append({'name':base+str(bit),'base':base,'bit':bit,'keep':keep,
                                'c':str(Q(rng.randrange(-6,7),3)),
                                'v':[str(Q(rng.randrange(-4,5),2))],'next':nxt})
        nodes.append({'name':name,'actions':actions})
    source = graph(nodes,[(-1,1)],Q(seed%4,3),('A','B','AB')[seed%3])
    abstract = deepcopy(source)
    if seed%4==1:
        for n in abstract['nodes']:
            for a in n['actions']:
                a['c'] = str(Q(a['c'])+Q(rng.randrange(-3,4),4))
    elif seed%4==2:
        abstract['eta'] = str(Q(source['eta'])+Q(1,2))
    elif seed%4==3:
        for n in abstract['nodes']:
            for a in n['actions']: a['v'] = ['0']
    return source,abstract


def many_paths(depth=64):
    nodes = []
    for i in range(depth):
        nxt = ['n'+str(i+1)] if i+1<depth else []
        actions = (pair('LEFT',True,0,[0],nxt)+pair('RIGHT',True,0,[0],nxt)+
                   pair('O',False,Q(-1,2),[1]))
        nodes.append({'name':'n'+str(i),'actions':actions})
    return graph(nodes,[(0,1)],root='n0')


def open_transfer_loss():
    # Source is bad everywhere. Abstract is bad only at 0 and 1, via two
    # DIFFERENT child histories; no comparison root falls in (0,1).
    source=graph([leaf('root',k=0,o=0,dim=1)],[(0,1)])
    left,right=leaf('left',k=0,o=0,dim=1),leaf('right',k=0,o=-1,dim=1)
    for a in left['actions']:
        if a['base']=='O':a['v']=['-1']
    for a in right['actions']:
        if a['base']=='O':a['v']=['1']
    return source,fork(left,right,[(0,1)])
